#include <stdio.h>

int solution(int loans[], int loans_len) {
    int count[10] = {0};
    int answer = 0, maxCount = 0;
    for (int i = 0; i < loans_len; i++) {
        int field = loans[i];
        count[field]++;
        if (count[field] > maxCount || (count[field] == maxCount && field > answer)) {
            maxCount = count[field];
            answer = field;
        }
    }
    return answer;
