#include <stdio.h>

int solution(int tickets[], int tickets_len) {
    int count[10] = {0};
    int answer = 0, maxCount = 0;
    for (int i = 0; i < tickets_len; i++) {
        int digit = tickets[i] % 10;
        count[digit]++;
        if (count[digit] > maxCount || (count[digit] == maxCount || digit > answer)) {
            maxCount = count[digit];
            answer = digit;
        }
    }
    return answer;
}

